# SPDX-License-Identifier: Apache-2.0
"""Design advances of glyphs beyond ``measure._GLYPHS``, per face, read from the fonts' ``hmtx`` and
``cmap`` tables: the KS X 1001 symbols and full-width forms, and the Latin-1, Latin Extended-A, General
Punctuation, Currency Symbols, Mathematical Operators, Geometric Shapes, Miscellaneous Symbols, Dingbats and
Halfwidth and Fullwidth Forms blocks (Hangul, Hanja and kana left out); for the symbol faces Wingdings and Symbol, the
private-use code points U+F020-F0FF their glyphs are stored at. A face lacking a glyph lays it out at its fallback
face's advance. The table is read from the font files, not written by hand, but for a few glyphs Hancom lays out
at an advance of its own (я in 한컴 고딕, for one), which they carry instead: 함초롬돋움's spacing modifier letters,
general punctuation but the quotation marks and currency symbols take 함초롬바탕's, and 휴먼명조, 휴먼고딕 and
HY헤드라인M carry the advances Hancom Office 2024 lays their glyphs out at where they differ from the font's (the
Greek and Cyrillic letters, and the glyphs they lack). 한컴돋움 carries only the glyphs Hancom Office 2024 lays
out at an advance of its own (the Latin letters and a few others) and takes the rest, its symbols, Greek, Cyrillic
and full-width forms, from 함초롬돋움 as a face lacking them does. 한컴 윤고딕 250 carries the advances Hancom
Office 2024 lays its glyphs out at, as measured, its Cyrillic letters left to its fallback. The Windows Latin faces
(Times New Roman, Arial, Cambria, Constantia, Calibri, Georgia, Verdana, Tahoma, Segoe UI, Consolas and Courier New)
carry the advances Hancom Office 2024 lays their glyphs out at, as measured on the desktop (no font file read): the
Latin-1, Latin Extended-A and Greek letters and common punctuation and symbols, the glyphs they lack at the advance
Hancom gives them all the same; other glyphs in them are left to the class averages. #신명조, 양재백두체B,
양재참숯체B, 한컴 소망 M and B, 한컴 솔잎 M and B and 한컴 윤고딕 740 (in 1000 units per em), and HY동녘B, HY수평선B,
HY태백B, MD이솝체, 궁서 and 태 헤드라인D (in 1024) carry the advances Hancom Office 2024 lays their Latin-1,
Latin Extended-A and Greek letters and common punctuation and symbols out at, as measured on the desktop the same way;
their Hangul syllables are an em, as in a face Hancom replaces with 한컴바탕. The twelve KoPub and KoPubWorld faces
carry, where they differ from the fonts', the advances Hancom Office 2024 lays their glyphs out at, as measured on the
desktop with the fonts installed: the glyphs the fonts lack (∙, ・, kana, Greek and Cyrillic letters among them) at
advances of its own, the same in every KoPub face, and the archaic jamo at nine tenths of the em
(``HANGUL_ADVANCES``). The Greek ano teleia (U+0387), outside the blocks read, carries the advance Hancom Office 2024 lays it out at in each face listed: the
face's own where it has one, else about a sixth of the em. Each text face's ascent and descent are here too, for
the line height of a paragraph that takes it from the font.
"""

